def below_threshold(l: list, t: int) -> bool:
    """Return True if all numbers in the list l are below threshold t."""
    return all(x < t for x in l)

def correct_bracketing(brackets: str) -> bool:
    """
    Returns True if every opening bracket has a corresponding closing bracket.
    """
    balance = 0
    for ch in brackets:
        if ch == '(':
            balance += 1
        elif ch == ')':
            balance -= 1
            if balance < 0:
                return False
    return balance == 0

def pluck(arr):
    """
    Returns the smallest even value and its index from the given array.
    If no even values exist or the array is empty, returns an empty list.
    """
    if not arr:
        return []

    smallest_even = None
    smallest_index = None

    for i, val in enumerate(arr):
        if val % 2 == 0:  # even
            if smallest_even is None or val < smallest_even:
                smallest_even = val
                smallest_index = i
            # If equal, we keep the earlier index (already smallest)

    if smallest_even is None:
        return []
    else:
        return [smallest_even, smallest_index]

def search(lst):
    """
    Returns the greatest integer x > 0 such that its frequency in lst is at least x.
    If no such integer exists, returns -1.
    """
    # Count frequencies of each integer
    freq = {}
    for num in lst:
        freq[num] = freq.get(num, 0) + 1

    # Find the maximum integer satisfying the condition
    max_val = -1
    for num, count in freq.items():
        if count >= num and num > max_val:
            max_val = num

    return max_val

def is_multiply_prime(a: int) -> bool:
    """
    Returns True if a is the product of exactly three prime numbers (with
    repetitions allowed), False otherwise.  Assumes a < 100.
    """
    # Quick reject: the smallest product of three primes is 2*2*2 = 8
    if a < 8:
        return False

    # Generate all primes up to 100 (since a < 100)
    limit = 100
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    # Try all ordered triples of primes (with repetition)
    for p in primes:
        if p > a:
            break
        for q in primes:
            if p * q > a:
                break
            for r in primes:
                product = p * q * r
                if product == a:
                    return True
                if product > a:
                    break
    return False

