def is_happy(s: str) -> bool:
    """
    Returns True if the string s is "happy":
    - length at least 3
    - every three consecutive characters are distinct
    Otherwise returns False.
    """
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i+1] or s[i] == s[i+2] or s[i+1] == s[i+2]:
            return False
    return True

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    # For n >= 2: total = 18 * 10^(n-2)
    return 18 * (10 ** (n - 2))

def encrypt(s: str) -> str:
    """
    Encrypts a string by shifting each lowercase letter forward by 4 positions
    in the alphabet, wrapping around from 'z' to 'a'. Non‑lowercase characters
    are left unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # shift by 4, wrap around 26 letters
            shifted = chr((ord(ch) - ord('a') + 4) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

def skjkasdkd(lst):
    """
    Returns the sum of the digits of the largest prime number in the input list.
    If no prime exists, returns 0 (but based on examples, at least one prime is present).
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_prime = 0
    for num in lst:
        if is_prime(num) and num > largest_prime:
            largest_prime = num

    # If no prime found (should not happen in given examples), return 0
    if largest_prime == 0:
        return 0

    # Sum the digits
    return sum(int(digit) for digit in str(largest_prime))

