def unique_digits(x):
    """
    Given a list of positive integers x, return a sorted list of all
    elements that have no even digit.

    Note: Returned list should be sorted in increasing order.
    """
    def all_odd_digits(n):
        # Check if every digit in n is odd
        return all(int(d) % 2 != 0 for d in str(n))

    # Filter numbers with only odd digits and sort the result
    return sorted([num for num in x if all_odd_digits(num)])

def histogram(test):
    """
    Given a string of space-separated lowercase letters, returns a dictionary
    containing the letters that appear most frequently and their count.
    If multiple letters have the same highest frequency, all of them are included.
    For an empty string, returns an empty dictionary.

    Example:
    >>> histogram('a b c')
    {'a': 1, 'b': 1, 'c': 1}
    >>> histogram('a b b a')
    {'a': 2, 'b': 2}
    >>> histogram('a b c a b')
    {'a': 2, 'b': 2}
    >>> histogram('b b b b a')
    {'b': 4}
    >>> histogram('')
    {}
    """
    if not test:                     # handle empty input
        return {}

    # split the string into words (handles multiple spaces correctly)
    words = test.split()
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1

    # find the maximum frequency
    max_count = max(freq.values())

    # return only the letters with that frequency
    return {k: v for k, v in freq.items() if v == max_count}

def valid_date(date):
    """
    Validates a date string in the format mm-dd-yyyy.
    Returns True if the date is valid, otherwise False.
