    return True

def split_words(txt):
    """
    Given a string of words, return a list of words split on whitespace.
    If no whitespace exists, split on commas ','.
    If no commas exist, return the number of lower-case letters with odd order
    in the alphabet (ord('a')=0, ord('b')=1, ... ord('z')=25).
    """
    # Check for whitespace
    if any(c.isspace() for c in txt):
        return txt.split()
    # Check for commas
    if ',' in txt:
        return txt.split(',')
    # Otherwise count lower-case letters with odd alphabet index
    count = 0
    for c in txt:
        if c.islower():
            # ord('a') = 97, so subtract 97 to get 0-based index
            if (ord(c) - ord('a')) % 2 == 1:
                count += 1
    return count

def intersection(interval1, interval2):
    # Compute the intersection interval
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    # No intersection
    if start > end:
        return "NO"

    # Length of intersection (end - start)
    length = end - start

    # Prime numbers are greater than 1
    if length < 2:
        return "NO"

    # Check if length is prime
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return "NO"
    return "YES"

def prod_signs(arr):
    """
    Returns the sum of magnitudes of integers multiplied by the product of all signs.
    Returns None for an empty array.
    """
    if not arr:
        return None

    product_sign = 1
    sum_abs = 0

    for x in arr:
        # Determine sign: 1 for positive, -1 for negative, 0 for zero
        if x > 0:
            sign = 1
        elif x < 0:
            sign = -1
        else:
            sign = 0

        product_sign *= sign
        sum_abs += abs(x)

    return product_sign * sum_abs

