    # Count digits
    digit_count = sum(1 for ch in file_name if ch.isdigit())
    if digit_count > 3:
        return 'No'

    # Count dots and split
    if file_name.count('.') != 1:
        return 'No'

    parts = file_name.split('.')
    name_part, ext_part = parts[0], parts[1]

    # Check name part
    if not name_part:
        return 'No'
    if not name_part[0].isalpha():
        return 'No'

    # Check extension part
    if ext_part not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

def x_or_y(n, x, y):
    """
    Returns x if n is a prime number, otherwise returns y.
    """
    if n <= 1:
        return y
    # Check divisibility from 2 to sqrt(n)
    i = 2
    while i * i <= n:
        if n % i == 0:
            return y
        i += 1
    return x

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None
    return hashlib.md5(text.encode()).hexdigest()
